                  {neighbours.slice(0, Math.max(1, Math.floor(filler / 2))).map(name => <div key={name} className="rounded-2xl border border-border bg-card p-5 opacity-40"><p className="text-sm font-medium">{name}</p></div>)}
                </div>}
