368	type Reviewed = { text: string; looked: string[]; remaining: string[] };
369	async function review(run: Run, { system, prompt, text, what, shots, accept }: {
370	  system: string; prompt: string; text: string; what: "document" | "module";
371	  shots: (text: string) => { shots: Shot[]; done: () => void } | null;
372	  accept: (text: string) => Promise<boolean>;
373	}): Promise<Reviewed> {
374	  let current = text, looked: string[] = [], remaining: string[] = [];
375	  for (let round = 0; round < LOOK_ROUNDS; round++) {
376	    const planned = shots(current);
377	    if (!planned) break;
378	    const seen = await lookAt(planned.shots, run.session).catch(previewUnavailable).finally(planned.done);
379	    if (!seen) break;
380	    looked = seen.map(shot => shot.label);
381	    remaining = seen.flatMap(shot => shot.problems.map(problem => `${shot.label}: ${problem}`));
382	    const report = `This is how your ${what} renders with the owner's real data (${looked.join("; ")}).\n${remaining.length ? `Measured problems:\n${remaining.map(problem => `- ${problem}`).join("\n")}` : "The measurements found nothing cut off, overlapping or unreadable."}\n\nLook at it as the owner would: calm, clear and readable at every size, nothing cut off, overlapping, crammed or empty. If it is good, reply with exactly OK. Otherwise reply with the whole fixed ${what} and nothing else.`;
383	    const { text: reply } = await design(run, system, [
384	      { role: "user", content: prompt },
385	      { role: "assistant", content: current },
386	      { role: "user", content: [{ type: "text", text: report }, ...seen.flatMap(shot => [{ type: "text" as const, text: shot.label }, { type: "file" as const, data: shot.png, mediaType: "image/png" }])] },
387	    ]);
388	    if (/^OK\.?$/i.test(reply.trim())) return { text: current, looked, remaining };
389	    if (!await accept(reply)) break;
390	    current = reply;
391	  }
392	  return { text: current, looked, remaining };
393	}
