415	  const [data, current] = await Promise.all([
416	    runArtifactQueries(input.queries, context, today(context)),
417	    supabase.from("artifact_versions").select("version, html").eq("workspace_id", workspace.id).eq("artifact_id", artifactId).order("version", { ascending: false }).limit(1).maybeSingle(),
418	  ]);
419	  if (current.error) throw current.error;
420	  let prompt = `${current.data ? `Current page (change it as the brief says, keep the rest):\n${current.data.html}\n\n` : ""}${ownerWords(run)}Brief:\n${input.brief}\n\nQueries:\n${JSON.stringify(input.queries)}\n\nData now (window.MONEO_DATA):\n${sample(data)}`;
421	  let text = "", model = "";
422	  for (let attempt = 0; ; attempt++) {
423	    ({ text, model } = await design(run, PAGE_DESIGNER, prompt));
424	    if (!/<[a-z]/i.test(text)) return { saved: false, errors: ["The designer returned no HTML; try again with a clearer brief."] };
425	    const errors = pageScriptErrors(text);
