427	    if (attempt === 2) return { saved: false, errors: [`The page's code did not parse, so the current version was kept: ${errors.join("; ")}`] };
428	    prompt = `${prompt}\n\nYour last version:\n${text}\n\nIts JavaScript does not parse, so the page would show nothing. Fix these and reply with the whole document again:\n${errors.join("\n")}`;
