439	  const touched = await supabase.from("artifacts").update({ title: input.title, updated_at: new Date().toISOString() }).eq("workspace_id", workspace.id).eq("id", artifactId);
440	  if (touched.error) throw touched.error;
441	  return { saved: true, pageVersion: version, note: "The Page tab shows it now.", ...lookNote(reviewed) };
442	}
