502	        let prompt = `${current?.data ? `Current card (change it as the brief says, keep the rest):\n${current.data.source}\n\n` : ""}${ownerWords(run)}Title (shown by the app): ${title}\nBrief:\n${brief}\n\nParams: ${JSON.stringify(params)}\n\nData now:\n${sample(data)}${otherData && other ? `\n\nData for ${JSON.stringify(other.values)} (same shape, for reference):\n${sample(otherData)}` : ""}`;
503	        for (let attempt = 0; attempt < 3; attempt++) {
504	          const { text, model } = await design(run, CARD_DESIGNER, prompt);
